-- 1. Logical Database Creation
CREATE DATABASE GoldAnalyticsDB;
GO

USE GoldAnalyticsDB;
GO

-- 2. External Table / View Creation over Gold Parquet File
CREATE VIEW vw_CountryCustomerSummary AS
SELECT *
FROM OPENROWSET(
    BULK 'https://rgsynapsedev01.dfs.core.windows.net/main/curated/country_customer_summary.parquet',
    FORMAT = 'PARQUET'
) AS [result];
GO

-- 3. Query the View
SELECT * FROM vw_CountryCustomerSummary;
